CREATE TABLE IF NOT EXISTS provider_credentials (provider TEXT PRIMARY KEY,encrypted_key TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS managed_models (id TEXT PRIMARY KEY,provider TEXT NOT NULL,model TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 50,context_window INTEGER NOT NULL DEFAULT 32768,capabilities TEXT NOT NULL DEFAULT '["chat"]',enabled INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
